html deklaratif
&lt;notif-element type="success" message="data berhasil disimpan!" duration="3000"
 visible="true"&gt;
&lt;/notif-element&gt;

javascript api
// membuat elemen notifikasi
const document.createelement(notif-element');
notif.setattribute('type', 'success');
notif.setattribute('message', 'data disimpan!');
notif.setattribute('duration', '3000');
document.body.appendchild(notif);

// method: show() dan hide()
notif.show(); // tampilkan notifikasi
notif.hide(); sembunyikan notifikasi

event listener
const document.queryselector('notif-element');

notif.addeventlistener('notif-show', (e) => {
 console.log('notifikasi ditampilkan:', e.detail);
});

notif.addeventlistener('notif-hide', disembunyikan:', e.detail);
});

